import { describe, expect, it } from 'vitest';
import {
  PYTHON_UNIDATA_VERSION,
  initials,
  pyDedent,
  renderBackgroundPatternSvg,
  renderHeroSvg,
  renderLogoSvg,
} from '../src/index';
import { SPACE_RANGES, UPPER_CASED_RANGES, type CodePointRange } from '../src/python-unicode';
import fixtureJson from './fixtures/assets-parity.json';

// Generated by services/langgraph/tests/test_assets_parity_fixture.py (Python is the reference).
interface PyKwargs {
  readonly brand_name: string;
  readonly primary: string;
  readonly secondary: string;
  readonly surface: string;
  readonly tagline?: string | null;
  readonly headline?: string;
  readonly audience?: string;
  readonly accent?: string;
}

interface Fixture {
  readonly protocol: string;
  readonly unidata_version: string;
  readonly cases: ReadonlyArray<{ readonly kind: 'logo' | 'pattern' | 'hero'; readonly kwargs: PyKwargs; readonly output: string }>;
  readonly space: readonly number[];
  readonly upper: Readonly<Record<string, string>>;
}

const fixture = fixtureJson as unknown as Fixture;

function render(kind: 'logo' | 'pattern' | 'hero', k: PyKwargs): string {
  const base = { brandName: k.brand_name, primary: k.primary, secondary: k.secondary, surface: k.surface };
  if (kind === 'logo') return renderLogoSvg({ ...base, tagline: k.tagline });
  if (kind === 'pattern') return renderBackgroundPatternSvg(base);
  return renderHeroSvg({ ...base, headline: k.headline ?? '', audience: k.audience ?? '', accent: k.accent ?? '' });
}

function expand(ranges: readonly CodePointRange[]): number[] {
  return ranges.flatMap(([lo, hi]) => Array.from({ length: hi - lo + 1 }, (_, i) => lo + i));
}

describe('@amc/assets parity with the Python reference', () => {
  it('uses the fixture protocol and Python Unicode tables', () => {
    expect(fixture.protocol).toBe('AMC-ASSETS-PARITY-1');
    expect(PYTHON_UNIDATA_VERSION).toBe(fixture.unidata_version);
    expect(expand(SPACE_RANGES)).toStrictEqual(fixture.space);
    expect(fixture.cases.length).toBeGreaterThan(300);
  });

  it('renders every fixture case byte-for-byte', () => {
    for (const c of fixture.cases) expect(render(c.kind, c.kwargs), JSON.stringify(c.kwargs)).toBe(c.output);
  });

  it("uppercases every code point exactly as Python's str.upper() for initials", () => {
    const cased = new Set(expand(UPPER_CASED_RANGES));
    expect([...cased].map(String)).toStrictEqual(Object.keys(fixture.upper));
    const spaces = new Set(fixture.space);
    const mismatches: string[] = [];
    for (let cp = 0; cp < 0x110000; cp += 1) {
      if ((cp >= 0xd800 && cp <= 0xdfff) || spaces.has(cp)) continue;
      const ch = String.fromCodePoint(cp);
      if (initials(`${ch}x`) !== (fixture.upper[String(cp)] ?? ch)) mismatches.push(cp.toString(16));
    }
    expect(mismatches).toStrictEqual([]);
  });
});

describe('@amc/assets Python string semantics', () => {
  it('splits on Python whitespace, not JS \\s', () => {
    expect(initials('a\x1cb')).toBe('AB');
    expect(initials('a﻿b')).toBe('A');
    expect(initials('   ')).toBe('B');
    expect(initials('ß ﬁ')).toBe('SSFI');
  });

  it('dedents like textwrap.dedent', () => {
    expect(pyDedent('  a\n    b\n  ')).toBe('a\n  b\n');
    expect(pyDedent('  a\r  b\n\tc')).toBe('  a\r  b\n\tc');
    expect(pyDedent('\t a\n\t b')).toBe('a\nb');
  });
});
